<?php declare( strict_types=1 ); namespace Inc\Controllers\Exam; use Inc\Contracts\ServiceInterface; use Inc\Core\BaseController; class ExamResultPageController extends BaseController implements ServiceInterface { public function register(): void { add_filter( 'template_include', [ $this, 'filterTemplateForResultPage' ], 99 ); add_filter( 'wp_title', [ $this, 'filterPageTitle' ], 10, 2 ); } public function filterTemplateForResultPage( string $template ): string { if ( isset( $_GET['exam_result_id'] ) ) { return $this->path( 'templates/exam-result.php' ); } return $template; } public function filterPageTitle( string $title, string $sep ): string { if ( isset( $_GET['exam_result_id'] ) ) { return 'Результат экзамена' . " {$sep} "; } return $title; } }
